    sampler = DWaveSampler()
    solver = CPLEX(solver=sampler)
    problem = SamplingProblem(qubo, solver=solver)
    solution = solver.sample(problem)

    # Compute penalty-adjusted QUBO energy
    penalty_adjusted_qubo_energy = 0
    for task in tasks['resources']:
        if task['variable'] in qpu_assignments.keys():
            penalty_adjusted_qubo_energy += (tasks['priority'][task['variable']] - 39) * (1 - np.log2(len(qpu_assignments[task['variable']] + 1))
        else:
